#include <Cellerator/compiler/ir/planning/implement_planning_ir_parser_printer_and_validator_v1.hh>
#include <cstdio>
#include <cstring>
namespace cellerator::compiler::ir::planning::v1 {
planning_text_status_v1 validate_planning_text_module_v1(const planning_text_module_v1&v) noexcept{return (!v.module.low&&!v.module.high)?planning_text_status_v1::invalid_module:planning_text_status_v1::ok;}
planning_text_status_v1 print_planning_ir_v1(const planning_text_module_v1&v,char*out,std::size_t cap,std::size_t*w) noexcept{if(!w)return planning_text_status_v1::invalid_argument;auto s=validate_planning_text_module_v1(v);if(s!=planning_text_status_v1::ok)return s;int n=std::snprintf(out,cap,"plan1 module=%016llx:%016llx alternatives=%u coverage=%u atoms=%u costs=%u evidence=%u selections=%u ext=%.*s",(unsigned long long)v.module.high,(unsigned long long)v.module.low,v.alternatives,v.coverages,v.atoms,v.costs,v.evidence,v.selections,(int)v.unknown_extension_bytes,v.unknown_extensions?v.unknown_extensions:"");if(n<0)return planning_text_status_v1::invalid_argument;*w=(std::size_t)n;return *w>=cap?planning_text_status_v1::insufficient_capacity:planning_text_status_v1::ok;}
planning_text_status_v1 parse_planning_ir_v1(const char*in,std::size_t bytes,char*ext,std::size_t cap,planning_text_module_v1*out) noexcept{if(!in||!out)return planning_text_status_v1::invalid_argument;unsigned long long hi=0,lo=0;unsigned a=0,c=0,t=0,k=0,e=0,s=0;int off=0;int n=std::sscanf(in,"plan1 module=%llx:%llx alternatives=%u coverage=%u atoms=%u costs=%u evidence=%u selections=%u ext=%n",&hi,&lo,&a,&c,&t,&k,&e,&s,&off);if(n!=8||off<=0||(std::size_t)off>bytes)return planning_text_status_v1::invalid_syntax;std::size_t eb=bytes-(std::size_t)off;if(eb>cap||(eb&&!ext))return planning_text_status_v1::insufficient_capacity;if(eb)std::memcpy(ext,in+off,eb);*out={{(std::uint64_t)lo,(std::uint64_t)hi},a,c,t,k,e,s,ext,eb};return validate_planning_text_module_v1(*out);}
}
